#pragma once
#include <cstdint>

// Internal full-graph HLS prototype, not a validated public board ABI.
// The caller must provide separate nonoverlapping regions for every pointer.
// This prototype validates lengths and relative scratch lifetimes, but does not
// enforce physical address windows, cross-region aliasing or AXI error recovery.
// Layout is 336 LE u32 words generated by B tooling.
extern "C" int griddehaze_frame_top(
    const std::int16_t* input,std::int16_t* output,std::int16_t* scratch,
    const std::int16_t* parameters,const std::uint32_t* layout,
    std::uint32_t input_bytes,std::uint32_t output_bytes,std::uint32_t scratch_bytes,
    std::uint32_t parameter_bytes,std::uint32_t layout_bytes,
    int height,int width,std::uint32_t model_id,std::uint32_t abi,
    std::uint32_t& completed_nodes,std::uint32_t& hardware_model,std::uint32_t& hardware_abi);

#ifndef __SYNTHESIS__
// Testbench observation only; not compiled into hardware, never supplies values.
void gdn_frame_observe(int node,const std::int16_t* values,std::uint32_t elements);
#endif
